amudim['7a'].translation = [
  { type: 'section', title: 'סיום הברכה ויום הגשמים' },
  { type: 'quote', aramaic: 'נימרינהו לתרוייהו: האל ההודאות ורוב ההודאות. אמר ר׳ אבהו: גדול יום הגשמים מתחיית המתים, דאילו תחיית המתים לצדיקים, ואילו גשמים בין לצדיקים בין לרשעים. ופליגא דרב יוסף, דאמר רב יוסף: מתוך שהיא שקולה כתחיית המתים, קבעוה בתחיית המתים.',
    translation: 'נאמר את שתיהן: ״האל ההודאות״ ו״רוב ההודאות״. ר׳ אבהו: יום הגשמים גדול מתחיית המתים, כי תחיית המתים היא רק לצדיקים, והגשם לכולם. וזה חולק על רב יוסף, שאמר: הגשם רק שקול לתחיית המתים, ולכן קבעו אותו בברכת ״מחיה המתים״.' },
  { type: 'quote', aramaic: 'אמר רב יהודה: גדול יום הגשמים כיום שניתנה בו תורה, שנאמר ״יערף כמטר לקחי״, ואין לקח אלא תורה, שנאמר ״כי לקח טוב נתתי לכם, תורתי אל תעזובו״. רבא אמר: יותר מיום שניתנה בו תורה, שנאמר ״יערף כמטר לקחי״ — מי נתלה במי? הוי אומר: קטן נתלה בגדול.',
    translation: 'רב יהודה: יום הגשמים כמו יום מתן תורה, כי התורה נמשלה למטר. רבא: אפילו יותר, כי במשל משווים את הקטן לגדול.' },
  { type: 'section', title: 'משלים לתורה' },
  { type: 'quote', aramaic: 'רבא רמי: כתיב ״יערף כמטר לקחי״ וכתיב ״תזל כטל אמרתי״. אם תלמיד חכם הגון הוא — כטל, ואם לאו — עורפהו כמטר.',
    translation: 'רבא: לתלמיד הגון התורה עדינה כטל; ולמי שאינו הגון היא ״עורפת״ כמו מטר.' },
  { type: 'quote', aramaic: 'תניא, היה ר׳ בנאה אומר: כל העוסק בתורה לשמה, תורתו נעשית לו סם חיים... וכל העוסק בתורה שלא לשמה, נעשית לו סם המות, שנאמר ״יערף כמטר לקחי״, ואין עריפה אלא הריגה, שנאמר ״וערפו שם את העגלה בנחל״.',
    translation: 'ר׳ בנאה: לשמה — סם חיים; שלא לשמה — סם המות, מלשון ״עריפה״.' },
  { type: 'quote', aramaic: 'אמר ליה ר׳ ירמיה לר׳ זירא: ליתי מר ליתני. אמר ליה: חלש לבאי ולא יכילנא. לימא מר מילתא דאגדתא. אמר ליה: הכי אמר ר׳ יוחנן: מאי דכתיב ״כי האדם עץ השדה״? וכי אדם עץ שדה הוא?! אלא... אם תלמיד חכם הגון הוא — ״ממנו תאכל ואותו לא תכרת״, ואם לאו — ״אותו תשחית וכרת״.',
    translation: 'ר׳ זירא, חלש מכדי ללמד הלכה, אמר אגדה בשם ר׳ יוחנן: מתלמיד חכם הגון לומדים; ממי שאינו הגון מתרחקים.' },
  { type: 'quote', aramaic: 'אמר ר׳ חמא ברבי חנינא: ״ברזל בברזל יחד״ — מה ברזל אחד מחדד את חבירו, אף שני תלמידי חכמים מחדדין זה את זה בהלכה. אמר רבה בר בר חנה: למה נמשלו דברי תורה כאש? מה אש אינו דולק יחידי, אף דברי תורה אין מתקיימין ביחידי.',
    translation: 'ברזל: שני תלמידים מחדדים זה את זה. אש: התורה לא מתקיימת אצל מי שלומד לבד.' },
  { type: 'quote', aramaic: 'והיינו דאמר ר׳ יוסי בר חנינא: ״חרב אל הבדים ונואלו״ — חרב על שונאיהן של תלמידי חכמים שעוסקין בד בבד בתורה, ולא עוד אלא שמטפשין, ולא עוד אלא שחוטאין.',
    translation: 'מי שלומד לבד ראוי לעונש, נעשה טיפש, ובא לידי חטא.' },
  { type: 'quote', aramaic: 'אמר רב נחמן בר יצחק: למה נמשלו דברי תורה כעץ? מה עץ קטן מדליק את הגדול, אף תלמידי חכמים קטנים מחדדים את הגדולים. והיינו דאמר ר׳ חנינא: הרבה למדתי מרבותי, ומחבירי יותר מרבותי, ומתלמידי יותר מכולן.',
    translation: 'עץ: הקטנים מדליקים את הגדולים. ר׳ חנינא למד הכי הרבה מתלמידיו.' },
  { type: 'quote', aramaic: 'רבי חנינא בר פפא רמי: ״לקראת צמא התיו מים״ ו״הוי כל צמא לכו למים״ — אם תלמיד הגון הוא, לקראת צמא התיו מים; ואי לא, הוי כל צמא לכו למים. רבי חנינא בר חמא רמי: ״יפוצו מעינותיך חוצה״ ו״יהיו לך לבדך״ — אם תלמיד הגון הוא, יפוצו; ואם לאו, יהיו לך לבדך.',
    translation: 'שתי סתירות, ואותו יישוב: לתלמיד הגון הולכים ומלמדים; לשאינו הגון — לא.' },
  { type: 'quote', aramaic: 'ר׳ חנינא בר אידי: למה נמשלו דברי תורה למים? מה מים מניחין מקום גבוה והולכין למקום נמוך, אף דברי תורה אין מתקיימין אלא במי שדעתו שפלה. ר׳ אושעיא: לשלשה משקין — מים, יין וחלב: מה הם אין מתקיימין אלא בפחות שבכלים, אף דברי תורה במי שדעתו שפלה.',
    translation: 'מים יורדים למקום נמוך; מים, יין וחלב נשמרים בכלי פשוט. כך התורה אצל הצנוע.' },
  { type: 'section', title: 'בת הקיסר ור׳ יהושע בן חנניה' },
  { type: 'quote', aramaic: 'כדאמרה ליה ברתיה דקיסר לר׳ יהושע בן חנניה: אי חכמה מפוארה בכלי מכוער! אמר לה: אביך רמי חמרא במני דפחרא? אמרה ליה: אלא במאי נירמי? אמר לה: אתון דחשיבתו רמו במאני דהבא וכספא. אזלה ואמרה ליה לאבוה; רמייא לחמרא במני דהבא וכספא ותקיף. אתו ואמרו ליה. אמר לה לברתיה: מאן אמר לך הכי? אמרה ליה: רבי יהושע בן חנניה. קריוהו. אמר ליה: אמאי אמרת לה הכי? אמר ליה: כי היכי דאמרה לי, אמרי לה. והא איכא שפירי דגמירי!',
    translation: 'בת הקיסר לעגה לר׳ יהושע על מראהו. הוא יעץ לה לשים את היין בכלי זהב וכסף, והיין החמיץ. כשנשאל למה, אמר: כמו שהיא אמרה לי, כך עניתי לה. הקיסר הקשה: הרי יש יפים שהם חכמים! (התשובה בדף ז:).' },
];

