amudim['7a'].tosafot = [
  { dh: 'כל העוסק בתורה שלא לשמה תורתו נעשית לו סם המות', content: '<p>וקשה, והלא אמרינן (פסחים נ:) ״לעולם יעסוק אדם בתורה אף על גב שאינה לשמה, שמתוך שלא לשמה בא לשמה״! ויש לומר: דתרי ״שלא לשמה״ הוי. דמה שאמרינן ״לעולם יעסוק בתורה אפילו שלא לשמה״ — היינו כלומר כדי שיקרא רבי, או כדי שיכבדוהו. ומה שאמרינן הכא ״כל העוסק בתורה שלא לשמה נעשה לו סם המות״ — היינו מי שלומד <b>לקנטר</b>.</p>' },
  { dh: 'אם תלמיד חכם הגון ממנו תאכל', content: '<p>פירוש: למוד לפניו. ואותו לא תכרות — כלומר לא תפרד ממנו לילך לפני רב אחר. ואם לאו — לא תלמוד לפניו. והא דאמרינן דלומדים מתלמיד חכם אף על פי שאינו הגון, כר׳ מאיר שהיה לומד לפני אחר במסכת חגיגה (טו:) — היינו דווקא תלמיד חכם (גדול), שיכול ללמוד לפניו ולא ילמוד ממעשיו. אבל אם אינו תלמיד חכם — אינו רשאי ללמוד לפניו.</p>' },
  { dh: 'אף דברי תורה וכו׳', content: '<p>וכן נמי אמרינן בעירובין (נה.): ״לא בשמים היא ולא מעבר לים היא״ — כלומר לא תמצא התורה במי שמגביה עצמו כשמים, שדעתו גבוה, ולא בסוחרים ההולכים במדינת הים. דאי ספרא — לא סייפא, ואי סייפא — לא ספרא. והכי נמי איתא התם: לא בסחרנין ולא בתגרין, ולא באיסטרולוגין — כלומר באותן שרואין בכוכבים. אמרו ליה לשמואל: והא מר איסטרולוגוס הוא! אמר להו: תיתי לי דלא מעיינא בהו אלא בעידן דנפקא למיא — פירוש: להטיל מים, ולא אני מבטל לעצמי.</p>' },
  { dh: 'אי הוו סנו הוו חכימי טפי', content: '<p>פירוש: אם היו שונאים היופי — הוו תלמידי חכמים ביותר.</p>' }
];

